package com.aadil.ecommerce.responses;import lombok.Getter;import java.time.LocalDateTime;@Getterpublic class APIResponse<T>{    private final boolean success;    private final String message;    private final int code;    private final T data;    private final LocalDateTime createdAt;    public static class Builder<T>{        private boolean success;        private String message;        private int code;        private T data;        private LocalDateTime createdAt = LocalDateTime.now();        public Builder<T> success (boolean success){            this.success = success;            return this;        }        public Builder<T> message (String message){            this.message = message;            return this;        }        public Builder<T> code (int code){            this.code = code;            return this;        }        public Builder<T> data (T data){            this.data = data;            return this;        }        public Builder<T> createdAt (LocalDateTime createdAt){            this.createdAt = createdAt;            return this;        }        public APIResponse<T> build (){            return new APIResponse<>(this);        }    }    public static <T> Builder<T> builder(){        return new Builder<>();    }    public APIResponse(Builder<T> builder) {        this.success = builder.success;        this.message = builder.message;        this.code = builder.code;        this.data = builder.data;        this.createdAt = builder.createdAt;    }    @Override    public String toString() {        return "APIResponse{" +                "success=" + success +                ", message='" + message + '\'' +                ", code=" + code +                ", data=" + data +                ", createdAt=" + createdAt +                '}';    }}